// Package gate implements unlock-gate: a Tang server that releases an ECMR
// exchange only under an explicit policy (docs/design.md §6).
package gate

import (
	"bytes"
	"crypto/ed25519"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"net/netip"
	"os"
	"regexp"
	"strings"

	"golang.org/x/crypto/ssh"
)

// Config is the JSON document generated by the NixOS module. It holds no
// secrets: Tang keys live in KeysDir and the Telegram token in a file.
type Config struct {
	GateID             string                  `json:"gate_id"`
	PublicListen       []string                `json:"public_listen"`
	MeshListen         []string                `json:"mesh_listen"`
	CtlSocket          string                  `json:"ctl_socket"`
	RequireSecurityKey bool                    `json:"require_security_key"`
	Clients            map[string]ClientConfig `json:"clients"`
	Telegram           *TelegramConfig         `json:"telegram,omitempty"`
}

type ClientConfig struct {
	KeysDir string `json:"keys_dir"`
	// AgentPublicKey is the client's Ed25519 key (base64url, 32 bytes) that
	// signs heartbeat, arm and disarm.
	AgentPublicKey string `json:"agent_public_key"`
	// Approvers are OpenSSH public key lines allowed to sign approvals.
	Approvers []string `json:"approvers"`
	// AllowFrom optionally restricts /rec to these source prefixes.
	AllowFrom []string `json:"allow_from"`
}

type TelegramConfig struct {
	TokenFile string `json:"token_file"`
	ChatID    string `json:"chat_id"`
}

var namePattern = regexp.MustCompile(`^[a-z0-9][a-z0-9-]{0,62}$`)

// LoadConfig reads and validates a config file.
func LoadConfig(path string) (*Config, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read config: %w", err)
	}
	return ParseConfig(data)
}

// ParseConfig decodes strictly (unknown fields are errors) and validates.
func ParseConfig(data []byte) (*Config, error) {
	var cfg Config
	if err := decodeStrict(data, &cfg); err != nil {
		return nil, fmt.Errorf("parse config: %w", err)
	}
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	return &cfg, nil
}

// decodeStrict decodes exactly one JSON value, rejecting unknown fields and
// trailing data.
func decodeStrict(data []byte, v any) error {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	if err := dec.Decode(v); err != nil {
		return err
	}
	if dec.More() {
		return errors.New("trailing data after JSON value")
	}
	return nil
}

func (c *Config) validate() error {
	if !namePattern.MatchString(c.GateID) {
		return fmt.Errorf("invalid gate_id %q", c.GateID)
	}
	if len(c.PublicListen) == 0 {
		return errors.New("public_listen is empty")
	}
	if len(c.MeshListen) == 0 {
		return errors.New("mesh_listen is empty")
	}
	if !strings.HasPrefix(c.CtlSocket, "/") {
		return errors.New("ctl_socket must be an absolute path")
	}
	if len(c.Clients) == 0 {
		return errors.New("no clients configured")
	}
	for name, client := range c.Clients {
		if err := client.validate(name, c.RequireSecurityKey); err != nil {
			return fmt.Errorf("client %s: %w", name, err)
		}
	}
	if c.Telegram != nil && (c.Telegram.TokenFile == "" || c.Telegram.ChatID == "") {
		return errors.New("telegram needs token_file and chat_id")
	}
	return nil
}

func (c ClientConfig) validate(name string, requireSK bool) error {
	if !namePattern.MatchString(name) {
		return fmt.Errorf("invalid client name %q", name)
	}
	if !strings.HasPrefix(c.KeysDir, "/") {
		return errors.New("keys_dir must be absolute")
	}
	if _, err := c.agentKey(); err != nil {
		return err
	}
	keys, err := c.approverKeys()
	if err != nil {
		return err
	}
	if requireSK {
		for _, k := range keys {
			if !isSecurityKey(k) {
				return fmt.Errorf("approver key type %s is not a security key", k.Type())
			}
		}
	}
	_, err = c.allowFrom()
	return err
}

func isSecurityKey(k ssh.PublicKey) bool {
	return k.Type() == ssh.KeyAlgoSKED25519 || k.Type() == ssh.KeyAlgoSKECDSA256
}

func (c ClientConfig) agentKey() (ed25519.PublicKey, error) {
	raw, err := base64.RawURLEncoding.DecodeString(c.AgentPublicKey)
	if err != nil || len(raw) != ed25519.PublicKeySize {
		return nil, errors.New("agent_public_key must be 32 bytes of unpadded base64url")
	}
	return ed25519.PublicKey(raw), nil
}

func (c ClientConfig) approverKeys() ([]ssh.PublicKey, error) {
	if len(c.Approvers) == 0 {
		return nil, errors.New("no approvers configured")
	}
	keys := make([]ssh.PublicKey, 0, len(c.Approvers))
	for _, line := range c.Approvers {
		key, _, _, _, err := ssh.ParseAuthorizedKey([]byte(line))
		if err != nil {
			return nil, fmt.Errorf("approver key: %w", err)
		}
		keys = append(keys, key)
	}
	return keys, nil
}

func (c ClientConfig) allowFrom() ([]netip.Prefix, error) {
	return parsePrefixes(c.AllowFrom)
}

func parsePrefixes(texts []string) ([]netip.Prefix, error) {
	prefixes := make([]netip.Prefix, 0, len(texts))
	for _, text := range texts {
		p, err := netip.ParsePrefix(text)
		if err != nil {
			return nil, fmt.Errorf("prefix %q: %w", text, err)
		}
		prefixes = append(prefixes, p.Masked())
	}
	return prefixes, nil
}

func prefixesContain(prefixes []netip.Prefix, addr netip.Addr) bool {
	for _, p := range prefixes {
		if p.Contains(addr) {
			return true
		}
	}
	return false
}
